## Why This Is Asked
Tests a clean DP formulation for segmentation with per-placement costs and wildcards. It also probes backtracking and memoization versus tabulation choices under a dictionary constraint.

## Key Concepts
- DP on string positions with a dictionary
- Memoization vs bottom-up tabulation
- Backtracking reconstruction of segmentation
- Handling wildcards and per-placement costs

## Code Example
```javascript
function minCost(s, dict) {
  const n = s.length;
  const memo = new Array(n+1).fill(null);
  const choice = new Array(n).fill(null);

  function costAt(i, w) {
    let cost = 0;
    for (let j = 0; j < w.length; j++) {
      if (s[i+j] !== '?' && s[i+j] !== w[j]) {
        cost++;
      }
    }
    return cost;
  }

  function dp(i) {
    if (i === n) return 0;
    if (memo[i] !== null) return memo[i];

    let best = Infinity;
    let bestWord = null;

    for (const w of dict) {
      if (i + w.length <= n) {
        const c = costAt(i, w) + dp(i + w.length);
        if (c < best) {
          best = c;
          bestWord = w;
        }
      }
    }

    memo[i] = best;
    choice[i] = bestWord;
    return best;
  }

  const minCost = dp(0);
  if (minCost === Infinity) return -1;

  // Reconstruct segmentation
  const words = [];
  let i = 0;
  while (i < n) {
    words.push(choice[i]);
    i += choice[i].length;
  }

  return { cost: minCost, words };
}
```

## Complexity
Time: O(n × sum|w|) where sum|w| is total length of all dictionary words
Space: O(n) for memoization and choice arrays

## Why This Is Asked

This problem tests practical DP skills: counting subsets, managing zeros, and comparing memoization vs tabulation.

## Key Concepts

- Subset sum counting
- Top-down memoization
- Bottom-up tabulation
- Modulo arithmetic and zero handling

## Code Example

```javascript
function countSubsetsTopDown(nums, target) {
  const n = nums.length;
  const memo = Array.from({length: n+1}, () => new Map());
  function dfs(i, t){
    if (t === 0) return 1;
    if (i === n) return 0;
    const key = t;
    if (memo[i].has(key)) return memo[i].get(key);
    let res = dfs(i+1, t);
    if (t >= nums[i]) res = (res + dfs(i+1, t - nums[i]));
    memo[i].set(key, res);
    return res;
  }
  return dfs(0, target);
}
function countSubsetsBottomUp(nums, target){
  const MOD = 1000000007;
  const dp = new Array(target+1).fill(0);
  dp[0] = 1;
  for (const v of nums){
    for (let w = target; w >= v; w--){
      dp[w] = (dp[w] + dp[w - v]) % MOD;
    }
  }
  return dp[target];
}
``` 

